<?php require_once 'db.php';require_once 'auth.php';adminSzukseges();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT b.*,r.riasztas_szam FROM bevetesek b LEFT JOIN riasztasok r ON r.id=b.riasztas_id WHERE b.id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)exit('A bevetés nem található.');if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM bevetes_tagok WHERE bevetes_id=?')->execute([$id]);$pdo->prepare('DELETE FROM bevetesek WHERE id=?')->execute([$id]);$pdo->commit();header('Location: bevetesek.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$hiba='A törlés nem sikerült.';}}$oldalCim='Bevetés törlése';require 'header.php';?><div class="card danger-card"><span class="eyebrow">FIGYELEM</span><h1>Bevetés törlése</h1><p>Biztosan törlöd a <strong>#<?=$b['id']?></strong> bevetést (<?=$b['riasztas_szam']?>)?</p><?php if(!empty($hiba)):?><div class="alert alert-danger"><?=htmlspecialchars($hiba)?></div><?php endif;?><form method="post" class="form-actions"><button class="btn btn-danger">Igen, törlés</button><a class="btn btn-light" href="bevetesek.php">Mégse</a></form></div><?php require 'footer.php';?>